// Hand-written declarations for an invented realtime server package. They
// follow the shape a real socket server library declares: a server that hands
// each accepted connection to a handler, namespaces carved off the server, a
// per-connection socket, and a broadcast operator.

export declare class BroadcastOperator {
  emit(event: string, ...args: unknown[]): boolean;
}

export declare class RemoteSocket {
  emit(event: string, ...args: unknown[]): boolean;
}

export declare class Socket<ListenEvents = any, EmitEvents = any> {
  readonly id: string;
  readonly broadcast: BroadcastOperator;
  emit(event: string, ...args: unknown[]): boolean;
  on(event: string, listener: (...args: any[]) => void): this;
  join(room: string | string[]): void | Promise<void>;
  leave(room: string): void | Promise<void>;
  to(room: string): BroadcastOperator;
}

export declare class Namespace<ListenEvents = any, EmitEvents = any> {
  emit(event: string, ...args: unknown[]): boolean;
  on(event: "connection", listener: (socket: Socket<ListenEvents, EmitEvents>) => void): this;
  to(room: string): BroadcastOperator;
}

export declare class Server<ListenEvents = any, EmitEvents = any> {
  constructor(httpServer?: unknown);
  emit(event: string, ...args: unknown[]): boolean;
  on(event: "connection", listener: (socket: Socket<ListenEvents, EmitEvents>) => void): this;
  of(name: string): Namespace<ListenEvents, EmitEvents>;
  to(room: string): BroadcastOperator;
}
